run_query_body:
let mut best: i128 = 0;
let mut have: bool = false;
let mut i: usize = t.n;
while i > 0
    invariant
        i <= t.n,
        valid_cols_t(t),
        have <==> exists|j: int| (i as int) <= j && j < (t.n as int) && row_hit(t, j),
        have ==> exists|j: int| (i as int) <= j && j < (t.n as int) && row_hit(t, j) && max_m_val(t, j) == best as int,
        forall|j: int| (i as int) <= j && j < (t.n as int) && row_hit(t, j) ==> max_m_val(t, j) <= best as int || !have,
    decreases i,
{
    i = i - 1;
    let a = t.a[i];
    let ghost old_have = have;
    let ghost old_best = best as int;
    if a > 100 {
        if !have || (a as i128) > best {
            best = a as i128;
        }
        have = true;
    }
    proof {
        let ii = i as int;
        assert(t.a@[ii] == a);
        assert(row_hit(t, ii) <==> a > 100);
        if a > 100 {
            assert(max_m_val(t, ii) == a as int);
            assert(have);
            assert(row_hit(t, ii) && max_m_val(t, ii) >= best as int);
            assert(exists|j: int| ii <= j && j < (t.n as int) && row_hit(t, j));
            if old_have {
                let w = choose|j: int| (ii + 1) <= j && j < (t.n as int) && row_hit(t, j) && max_m_val(t, j) == old_best;
                assert(row_hit(t, w));
            }
            assert(exists|j: int| ii <= j && j < (t.n as int) && row_hit(t, j) && max_m_val(t, j) == best as int);
        } else {
            if have {
                assert(old_have);
                assert(exists|j: int| (ii + 1) <= j && j < (t.n as int) && row_hit(t, j));
            }
        }
    }
}
let mut res: Vec<OutRow> = Vec::new();
res.push(OutRow { m: best });
res
